def find_board_words(board, words):
    from collections import Counter
    available = Counter(char for row in board for char in row)
    trie = {}
    for word in words:
        if any(count > available[char] for char, count in Counter(word).items()):
            continue
        node = trie
        for char in word:
            node = node.setdefault(char, {})
        node["$"] = word
    result = []
    rows, columns = len(board), len(board[0])
    def search(r, c, parent):
        char = board[r][c]
        node = parent[char]
        word = node.pop("$", None)
        if word is not None:
            result.append(word)
        board[r][c] = "#"
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < columns and board[nr][nc] in node:
                search(nr, nc, node)
        board[r][c] = char
        if not node:
            del parent[char]
    for r in range(rows):
        for c in range(columns):
            if board[r][c] in trie:
                search(r, c, trie)
    return result

